def validate_feed(url):
    """
    Before doing anything else, check that the RSS feed is actually reachable
    and returning valid content. This prevents silent failures — if the feed
    is down or the URL changes, you'll know immediately instead of just not
    getting notifications and wondering why.

    Returns (True, feed_object) if all good, or (False, error_message) if not.
    """
    print(f"[→] Validating feed: {url}")

    # Step 1: Check the URL is reachable at all (basic HTTP check)
    try:
        response = requests.get(
            url,
            timeout=10,
            headers={
                # Pretend to be a normal browser — polite and avoids any bot filters
                "User-Agent": "Mozilla/5.0 (compatible; personal RSS reader)"
            },
        )
        if response.status_code != 200:
            return (
                False,
                f"Feed URL returned HTTP {response.status_code}. The feed may have moved or been removed.",
            )
    except requests.exceptions.ConnectionError:
        return (
            False,
            "Could not connect to digit.in. Check your server's internet connection.",
        )
    except requests.exceptions.Timeout:
        return False, "Request timed out. digit.in may be slow or down."
    except Exception as e:
        return False, f"Unexpected network error: {e}"

    # Step 2: Parse the feed and check it actually contains articles
    # feedparser.parse() never crashes — if it fails it just returns an empty object
    feed = feedparser.parse(url)

    if feed.bozo and not feed.entries:
        # 'bozo' is feedparser's flag for "this doesn't look like valid RSS"
        return (
            False,
            f"Feed content is invalid or not parseable as RSS. Error: {feed.bozo_exception}",
        )

    if not feed.entries:
        return (
            False,
            "Feed was fetched but contains no articles. It may be empty or the format has changed.",
        )

    # All good — return the parsed feed so we don't have to fetch it again
    print(f"[✓] Feed is valid. Found {len(feed.entries)} articles in feed.")
    return True, feed

def load_seen_articles():
    """Read seen_articles.txt and return a set of already-notified URLs."""
    if not os.path.exists(SEEN_FILE):
        return set()
    with open(SEEN_FILE, "r") as f:
        return set(line.strip() for line in f if line.strip())

def send_notification(title, url):
    """Send a push notification via ntfy.sh."""
    try:
        requests.post(
            f"https://ntfy.sh/{NTFY_TOPIC}",
            headers={
                "Title": "New article by Vyom on Digit",
                "Tags": "newspaper",
                "Click": url,
            },
            data=title.encode("utf-8"),
            timeout=10,
        )
        print(f"[✓] Notified: {title}")
    except Exception as e:
        print(f"[✗] Failed to send notification: {e}")

