            }}
          >
            {(["cash", "debit", "credit"] as PaymentMethod[]).map((m) => (
              <button
                key={m}
                className={`chip${paymentMethod === m ? " active" : ""}`}
                onClick={() => setPaymentMethod(m)}
                style={{ borderRadius: "var(--radius)", padding: "10px" }}
              >
                {m}
              </button>
            ))}
          </div>
        </div>

        {walletList.length > 1 && (
          <div>
            <div className="section-label">wallet</div>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              {walletList.map((w) => (
                <button
                  key={w.id}
                  className={`chip${walletId === w.id ? " active" : ""}`}
                  onClick={() => setWalletId(w.id)}
                >
                  {w.name}
                </button>
              ))}
            </div>
          </div>
        )}

        <div>
          <div className="section-label">date</div>
          <input
            className="input"
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            style={{ fontFamily: "var(--font-mono)", fontSize: 13 }}
          />
        </div>

        {error && (
          <div
            style={{
              fontSize: 12,
              color: "var(--danger)",
              fontFamily: "var(--font-mono)",
            }}
          >
            {error}
          </div>
        )}

        <button
          className="btn btn-primary btn-full"
          onClick={handleSubmit}
          disabled={loading}
          style={{
            height: 48,
            fontSize: 13,
            fontFamily: "var(--font-mono)",
            letterSpacing: "0.08em",
          }}
        >
          {loading ? "saving..." : "add expense"}
        </button>
      </div>
    </div>
  );
}

